from pathlib import Path
import json,re
B=Path(__file__).parent
r=json.loads((B/'numerical_results.json').read_text(encoding='utf8'))
TITLE='Численный метод согласованного выбора образовательных действий при ограничениях на риск и ресурсы'
TITLE_EN='A Numerical Method for Coordinated Selection of Educational Actions under Risk and Resource Constraints'
abstract=('Рассматривается задача выбора образовательных и диагностических действий для группы обучающихся при ограниченной ёмкости общих ресурсов. Предлагается схема численного решения конечной двухэтапной задачи: построение допустимых действий по апостериорному ограничению риска, вычисление ожидаемой ценности диагностики и согласованное распределение ресурсов. Состояния предпосылок описываются бета-распределениями; для целочисленных параметров и рационального порога риск вычисляется в точной рациональной арифметике. Целевая функция представляет ожидаемые потери от преждевременного перехода, отсрочки и дополнительной проверки. После округления выигрышей вниз применяется динамическое программирование с удалением доминируемых состояний. Доказаны ресурсная допустимость результата и аддитивная оценка погрешности, равная произведению числа заявок на шаг округления. На 30 малых синтетических задачах эталонное решение совпало с полным перебором. На 20 наборах от 24 до 192 заявок исследованы точность, затраты вычислений и отличие от жадного распределения. Раздельное планирование нарушило общий бюджет во всех этих наборах. Результаты относятся к вычислительной постановке; улучшение качества обучения и применимость оценочных потерь требуют отдельной эмпирической проверки.')
abstract_en=('This paper considers coordinated selection of educational and diagnostic actions for a cohort under shared resource constraints. A finite two-stage decision model combines posterior risk screening, predictive evaluation of additional observations, and resource allocation. Prerequisite states follow beta distributions. For integer posterior parameters and a rational threshold, risk tests and diagnostic values are computed using exact rational arithmetic. The objective accounts for premature progression, unnecessary deferral, and the cost of assessment. Candidate gains are rounded down and optimized by dynamic programming with dominance pruning. Feasibility is established, together with an additive objective error bound equal to the number of requests multiplied by the rounding step. An exact reference implementation agrees with exhaustive enumeration on thirty small synthetic instances. Twenty larger instances contain between twenty-four and one hundred ninety-two requests. The study reports allocation quality, computation time, and differences from a resource-normalized greedy policy. Independent planning exceeds shared capacities in every larger instance. The method addresses a restricted planning horizon with fixed prerequisites and a single diagnostic batch. The numerical findings establish computational properties within this model; they do not establish learning effectiveness, empirical calibration of posterior risk, or validity of the assumed educational loss values.')
assert 180<=len(abstract_en.split())<=200,len(abstract_en.split())
blocks=[]
def h(t):blocks.append({'type':'heading','text':t})
def sub(t):blocks.append({'type':'subheading','text':t})
def p(t):blocks.append({'type':'paragraph','text':t})
def eq(i):blocks.append({'type':'equation','id':i})
def table(n,title,headers,rows,widths):blocks.append({'type':'table','number':n,'title':title,'headers':headers,'rows':rows,'widths':widths})
def f(x,n=4):return f'{x:.{n}f}'.replace('.',',')

h('Введение')
p('Интеллектуальная обучающая система должна согласовывать индивидуальные рекомендации с доступными средствами проверки. Если нескольким студентам одновременно назначена трудоёмкая диагностика, корректное индивидуальное решение может породить невыполнимый общий план. Возникает вычислительная задача, в которой неопределённость состояния определяет допустимые действия, а ресурсные ограничения связывают решения разных обучающихся.')
p('Модели отслеживания знаний позволяют оценивать состояние по истории ответов [1], а графы знаний – формировать допустимые связи учебного содержания [2]. При использовании генеративных инструментов правильный артефакт дополнительно требует проверки самостоятельности выполнения [3]. Поэтому в рассматриваемом методе входом служат подтверждённые самостоятельные бинарные свидетельства. Обработка ошибок автоматического оценщика является отдельной задачей; представленный расчёт не устраняет их посредством апостериорного порога.')
p('Обзоры моделей обучающегося [12], объяснимого отслеживания знаний [13] и гибридных подходов [14] показывают разнообразие способов описания состояния. В рассматриваемой короткой диагностике используется статическая сопряжённая модель, пригодность которой определяется сопоставимостью заданий и условиями самостоятельности. Графовое планирование [15] задаёт содержательные связи; согласование проверок по общим ресурсам составляет отдельную вычислительную задачу.')
p('Разделение функций человека и ИИ рассматривается в [16]. Исследования обучения с генеративной помощью показывают зависимость результата от организации поддержки и последующего самостоятельного контроля [17], [18]. Работа о GigaCode [25] характеризует возможности кодового ассистента; её выводы не используются как подтверждение эффективности предлагаемого правила допуска.')

p('Адаптивный выбор учебных действий с учётом времени и экспертных ограничений уже исследуется, в частности с помощью многоруких бандитов [4]. При фиксированном наборе альтернатив общая ёмкость ресурсов приводит к вариантам задачи о рюкзаке с множественным выбором [5]–[7]; обзор задач с одним рюкзаком дополняет эту классификацию [22]. Динамическое программирование и отношения доминирования относятся к известным средствам её решения. Планирование диагностики опирается на теоретико-решенческое понимание ценности информации [8]. Современные обзоры [20], [21] связывают выбор дизайна с целью получения данных. Здесь диагностическая ценность определяется ожидаемой терминальной потерей, а не только информационным выигрышем.')
p('Цель работы – построить и проверить специализированную схему численного решения, которая связывает эти компоненты в конечной задаче согласованного назначения. Основной результат включает точный тест риска для выбранного класса апостериорных состояний, вычисление потерь после возможных исходов диагностики и ресурсное согласование с заданной аддитивной точностью. Новым общим алгоритмом решения задачи о рюкзаке эта схема не объявляется. Исследуется частный вычислительный блок адаптивного управления междисциплинарной подготовкой; состав всей четырёхлетней программы в данной статье не оптимизируется.')

h('Постановка задачи')
sub('Состояние и допустимость перехода')
p('Рассмотрим S заявок на переход к следующему учебному модулю. У каждой заявки s имеются две обязательные предпосылки j=1,2. Например, для перехода от алгоритмов поиска к анализу индексного доступа в СУБД ими могут быть понимание инварианта и оценка вычислительной стоимости. Структура перехода и содержательная проверка переноса утверждаются заранее. Здесь они считаются выполненными внешними условиями; вычислитель оценивает достаточность двух исходных предпосылок.')
p('В коротком интервале планирования вероятность самостоятельного успеха θₛⱼ считается постоянной. При априорном Beta(1,1), nₛⱼ независимых испытаниях и zₛⱼ успехах используется сопряжённое обновление:')
eq(1)
p('Повторы одного шаблона, работы с внешней помощью и неподтверждённые оценки не образуют дополнительные независимые испытания. Различие версий и происхождения свидетельств задаётся до применения (1). Содержательная связь задания с утверждением об обучающемся соответствует логике проектирования оценивания на основе свидетельств [19]. Параметры разных предпосылок апостериорно независимы – это допущение расчёта ожидаемых потерь, которое подлежит проверке при использовании реальных данных.')
p('Обозначим через Iτ(a,b) регуляризованную неполную бета-функцию, через τ порог освоения, а через δ допустимый апостериорный риск. Вероятность выполнения обеих предпосылок pₛ и верхняя граница риска ρₛ определяются выражениями')
eq(2)
p('Обозначения θₛⱼ, τ и δ сохраняют смысл вероятности самостоятельного успеха, порога и бюджета риска. Вариант с заранее равным делением требует Iτ(aₛⱼ,bₛⱼ)≤δ/2 для каждой предпосылки. Здесь применяется общее достаточное условие на их сумму ρₛ≤δ, поэтому множество допустимых состояний может быть шире. Все дальнейшие расчёты относятся к этому явно заданному варианту.')
p('Немедленный переход допустим при ρₛ≤δ. Неравенство объединения обеспечивает Pr(хотя бы одна θₛⱼ<τ | данные)≤ρₛ и без независимости предпосылок; произведение в pₛ использует независимость. Параметр δ относится к одной заявке в фиксированном состоянии, не задаёт частоту ошибок оценщика или общий риск группы. При изменении состояния после диагностики допустимость проверяется заново.')
sub('Двухэтапные потери и диагностика')
p('Терминальное решение состоит в переходе A либо отсрочке W. Потеря ошибочного перехода равна cₐ, а необоснованной отсрочки – c𝓌. Ожидаемые потери Lₛ(A)=cₐ(1−pₛ), Lₛ(W)=c𝓌pₛ. Текущее значение V(ηₛ) – минимум по допустимым терминальным действиям, где ηₛ=((aₛ₁,bₛ₁),(aₛ₂,bₛ₂)). Отсрочка всегда допустима и в данной постановке не расходует общие ресурсы. Она обеспечивает существование решения при любом неотрицательном бюджете.')
p('Дополнительная альтернатива Dⱼq проверяет одну предпосылку j пакетом из q новых самостоятельных заданий. Предполагается, что диагностика даёт наблюдения, а не изменяет θ в течение пакета. Для H успехов предиктивное распределение имеет вид')
eq(3)
p('Здесь (a)ₕ=a(a+1)…(a+h−1), (a)₀=1. При H=h параметры проверяемой предпосылки заменяются на (a+h,b+q−h), остальные сохраняются; новое состояние обозначено ηₛⱼq(h). После этого выполняется допустимое терминальное решение. Полная ожидаемая потеря диагностики включает её прямую стоимость d_q:')
eq(4)
p('Для каждой заявки строится множество Aₛ: оптимальное немедленное терминальное действие с потерей V(ηₛ) и диагностические альтернативы. Диагностика с неотрицательными ресурсными затратами и потерей не меньше V(ηₛ) удаляется, поскольку доминируется терминальным действием. Не требуется заранее фиксировать, что неопределённость обязательно приводит к проверке: при неинформативном или дорогом пакете метод выбирает отсрочку.')
sub('Общие ресурсные ограничения')
p('Каждая альтернатива a потребляет tₛₐ единиц ресурса преподавательской проверки и cₛₐ единиц ресурса запуска контрольных задач. Их целочисленные бюджеты равны T и C. Ресурсные единицы являются элементами модели планирования; их перевод в минуты или вычислительное время требует измерений. Через gₛₐ=V(ηₛ)−Lₛ(a)≥0 обозначим ожидаемое уменьшение потерь относительно плана без дополнительной диагностики. Задача согласования имеет вид')
eq(5)
p('Переменная xₛₐ равна единице для выбранной альтернативы, причём каждой заявке назначается ровно одно действие. Минимальная суммарная потеря равна J*=ΣₛV(ηₛ)−G*. Связь между заявками возникает только через бюджеты. Общие учебные занятия с эффектом для нескольких заявок, изменение состава модулей и многошаговое обучение в (5) не включены.')

h('Схема численного решения')
sub('Точный расчёт риска и ожидаемых потерь')
p('Для положительных целых a,b неполная бета-функция выражается конечной биномиальной суммой [9]. При τ=4/5 она вычисляется в рациональной арифметике:')
eq(6)
p('Это известное тождество, используемое как вычислительный компонент. Для рациональных стоимостей и целого q распределение (3), значения (4) и тест ρ≤δ также рациональны. Сравнение риска с порогом выполняется без округления в двоичный float. Важность разделения арифметической погрешности и смысла исходных данных следует из общих свойств вычислений с плавающей точкой [10]. Точность арифметики не исправляет неверно заданный статистический закон.')
p('Суммы кэшируются по парам (a,b); предиктивные пакеты – по состоянию, j и q. Для больших историй растёт длина целых чисел, поэтому рациональный вариант не объявляется универсально быстрым. Его область – умеренные объёмы независимых свидетельств и конечный набор диагностик. При нецелых параметрах или вещественных весах потребуются другой численный оценщик риска и отдельный контроль его погрешности. Классические устойчивые процедуры неполной бета-функции представлены в [23]; используемая здесь конечная рациональная сумма (6) является другим вычислительным вариантом.')
sub('Округление выигрышей и динамическое программирование')
p('Выбирается шаг ε>0; каждому выигрышу сопоставляется целое hₛₐ=⌊gₛₐ/ε⌋. Ресурсы и допустимость не округляются. По заявкам последовательно строится множество состояний (t,c,H), где H – сумма округлённых выигрышей. Для каждого занятого ресурса хранится максимальное H. Рекурсия для значения Fₛ(t,c) имеет вид')
eq(7)
p('Начальное условие F₀(0,0)=0; недостижимым состояниям, в том числе с отрицательными ресурсными индексами, соответствует −∞. Переходы с t>T или c>C отбрасываются. Вместе со значением хранится предшественник для восстановления плана. Если два состояния имеют одинаковые ресурсы, сохраняется лучшее значение; при равенстве используется детерминированный порядок альтернатив.')
p('На каждом слое удаляются состояния, доминируемые по обоим ресурсам и значению. Состояние (t,c,H) можно исключить при наличии отличающегося состояния (t′,c′,H′), для которого')
eq(8)
p('Сортировка по t,c и префиксный максимум по c позволяют проверять доминирование деревом Фенвика. Этот приём уменьшает число хранимых состояний, не вводя дополнительной приближённости. Используются точные сравнения целых H; риск не участвует в эвристическом отбрасывании, поскольку проверен при построении и последующем выполнении альтернатив.')
p('Алгоритм состоит из шести действий. 1) Зафиксировать версии графа, свидетельств, порогов и стоимостей. 2) Вычислить терминальные потери и допустимость. 3) Перебрать исходы каждого диагностического пакета и сформировать Aₛ. 4) Округлить выигрыши вниз. 5) Выполнить рекурсию (7) с удалением доминируемых состояний. 6) Восстановить альтернативы и независимо проверить оба бюджета. После фактической диагностики обновить состояние и применить предусмотренное терминальное решение.')

h('Свойства метода')
p('Утверждение 1. Для конечных Aₛ и целочисленных неотрицательных ресурсов рекурсия без округления выигрышей находит оптимум (5). Удаление состояний по (8) сохраняет этот оптимум. Доказательство проводится индукцией по s: каждый допустимый план первых s заявок получается добавлением одной альтернативы к допустимому префиксу. Продолжение доминируемого префикса может быть применено к доминирующему, поскольку для оставшихся заявок множества альтернатив одинаковы и доступных ресурсов не меньше. Значение такого продолжения не ухудшается.')
p('Утверждение 2. Для выбранного по округлённым выигрышам плана xε сохраняются ресурсная допустимость и оценка')
eq(9)
p('Действительно, для любого плана с S альтернативами εΣh≤G<εΣh+Sε. Максимальность округлённой суммы даёт εΣh(xε)≥εΣh(x*). Отсюда G(xε)≥G*−Sε. Поскольку план xε допустим для исходной задачи, G(xε)≤G*. Переход от выигрышей к потерям даёт (9). Ресурсы и наборы действий при округлении не меняются. В реализации не требуется вычислять неизвестный G*: для заданной допустимой погрешности η достаточно выбрать ε≤η/S.')
p('При A=maxₛ|Aₛ| плотный вариант требует O(SA(T+1)(C+1)) переходов. Значения двух соседних слоёв занимают O(TC) памяти; прямое хранение всех предшественников для восстановления – O(STC). Для разреженного слоя из K кандидатов удаление доминируемых состояний требует O(K log K+K log(C+1)) операций. Эти оценки относятся к арифметическим операциям; стоимость длинных целых учитывается отдельно. Алгоритм псевдополиномиален по ресурсным бюджетам, а не полиномиален по длине их двоичной записи. Оценка (9) сама по себе не превращает его в полностью полиномиальную схему приближения.')
p('Апостериорное ограничение относится к каждому разрешённому переходу при принятой модели наблюдений. После диагностической альтернативы оно проверяется для каждого реализованного исхода. Общий ресурсный план не выдаёт разрешение на переход заранее. Модельное ожидание потерь, точность вычисления этого ожидания и реальное педагогическое качество решения являются разными характеристиками.')

h('Вычислительный эксперимент')
sub('Протокол и сравниваемые решения')
p('Испытания выполнены на синтетических заявках без персональных данных и результатов обучения. Использованы τ=4/5, δ=1/20, cₐ=10, c𝓌=1, d_q=q/100 и q∈{1,3}. Стоимости заданы в условных единицах. Для истории n∈{8,12,16,20,24,32,40,48,64} и f∈{0,…,6} неуспехов формируется состояние Beta(n−f+1,f+1). Список историй строится вложенными циклами по n, затем f в указанном порядке; из него перебираются упорядоченные пары. Выделяется библиотека 159 пар, для которых хотя бы одна диагностика уменьшает ожидаемую потерю.')
p('Три из четырёх заявок генерируются из этой библиотеки, каждая четвёртая – из полного множества пар историй. Это намеренное обогащение задач случаями выбора диагностики; его нельзя трактовать как частоты состояний в учебной группе. Генератор задан рекуррентно: u←(1664525u+1013904223) mod 2³², начальное u равно seed. При каждом обращении u сначала обновляется; индекс элемента – остаток u по размеру списка. Из библиотеки одним обращением выбирается пара, для каждой четвёртой заявки двумя обращениями выбираются две исходные истории. Сначала выбирается состояние; затем для диагностик в порядке j=1,2 и q=1,3 формируются t=q+(u mod 3) и c=q(1+u mod 4), с отдельным обновлением u перед каждой стоимостью. Параметры ресурсов генерируются для всех четырёх диагностик до исключения неполезных вариантов.')
p('Для малых задач использованы S∈{4,6,8}, seed=1,…,10; решения эталонного рационального алгоритма сравнены с полным перебором всех комбинаций альтернатив. Основная серия содержит S∈{24,48,96,192}, seed=1,…,5: всего 20 наборов. Бюджеты T=⌊3S/5⌋, C=⌊9S/10⌋. Шаг основного метода ε=10⁻⁴. Ресурсные пределы и стоимость ошибок одинаковы для сравниваемых алгоритмов.')
p('Эталон использует те же конечные альтернативы и рациональные выигрыши без округления. Жадный алгоритм сортирует положительные альтернативы по g/(t/T+c/C) и последовательно включает их при наличии бюджета и отсутствии ранее выбранной диагностики этой заявки. Раздельное планирование выбирает минимум потерь для каждой заявки без общих ограничений; его недопустимость оценивается отдельно. Базовый план использует только немедленные терминальные действия. Последний задаёт нулевой выигрыш, но не означает автоматический допуск всех заявок.')
p('Реализация использует Python 3.12.14, стандартный модуль fractions [11] и однопоточный расчёт на AMD Ryzen 5 5500U под Windows 11. Время согласования измерено после подготовки альтернатив; для округлённого метода взята медиана трёх запусков, для каждой размерности затем медиана пяти наборов. Подготовка вероятностных значений и генерация входов в эти интервалы не входят. Эталон выполнен по одному запуску на набор; его время приводится как ориентир, без вывода о стабильном коэффициенте ускорения.')
sub('Результаты и анализ чувствительности')
p('В 30 малых задачах эталон совпал с полным перебором по точному рациональному значению целевой функции. На основной серии все восстановленные планы метода удовлетворяли бюджетам, а фактический разрыв при ε=10⁻⁴ оказался равен нулю относительно эталона. Это результат данных 20 наборов, а не усиление общей оценки (9). Раздельное планирование нарушило хотя бы один общий бюджет в 20 из 20 наборов.')
table('I','Согласование при ε=10⁻⁴',['S','T / C','Время, с','Эталон, с','Разрыв жадного, %'],[[str(x['n']),str(x['T'])+' / '+str(x['C']),f(x['medianDpMs']/1000,3),f(x['medianExactMs']/1000,3),f(x['greedyRelativeGapPercent'],2)] for x in r['summary']],[.7,1.5,1.8,1.8,2.7])
p('В таблице I разрыв жадного решения определён как 100(G*−Gж)/G* и усреднён по пяти наборам. Он характеризует недобор модельного уменьшения потерь, не долю ошибочных образовательных решений. Для S=192 средний выигрыш метода равен 28,2617 при базовой суммарной потере 146,3692; жадный выбор даёт 27,6674. Максимальный сохранённый слой основного метода содержал 8314 состояний при ресурсной сетке 116×173. Увеличение числа заявок и бюджетов заметно повышает стоимость согласования, что соответствует псевдополиномиальной структуре алгоритма.')
table('II','Точность для S=48, seed=1, T=28, C=43',['ε','Jε−J*','Граница Sε','Пик состояний'],[[f(x['epsilon'],4),f(x['gap'],6),f(x['bound'],4),str(x['peak'])] for x in r['sensitivity']],[1.7,2.3,2.3,2.2])
p('Таблица II показывает, что более грубое округление уменьшает число сохранённых состояний и может изменить выбранный план. При ε=0,01 разрыв равен 0,003238 и существенно меньше гарантированной границы 0,48. При ε=0,001 и 0,0001 в этом наборе восстановлен эталонный выигрыш. Зависимость числа состояний от ε не является гарантированно монотонной для любых входов: отношения доминирования меняются дискретно.')
blocks.append({'type':'figure','file':'budget.png','title':'Рис. 1. Уменьшение ожидаемых потерь при изменении двух бюджетов для S=48, seed=1'})
p('На рис. 1 оба бюджета изменяются одновременно от нуля до T=28, C=43 с округлением вниз до целых значений. Полученные выигрыши в пяти точках равны 0; 2,5519; 4,3106; 5,5975; 6,9248. При нулевом бюджете сохраняется допустимый терминальный план. Эти результаты иллюстрируют ресурсный компромисс выбранной задачи; индивидуальный эффект обучения в них не измеряется.')
p('Дополнительный пример показывает роль оценки ценности информации. Для η=((16,1),(24,1)) получены p=0,967263 и ρ=0,032870. Переход допустим, его ожидаемая потеря составляет 0,327369. Проверка первой предпосылки одним заданием уменьшает ожидаемую потерю до 0,317004 с учётом стоимости; пакет из трёх заданий даёт 0,331768. Поэтому увеличение числа проверок само по себе не делает действие предпочтительным. Конкретный выбор полезной диагностики всё равно зависит от общих бюджетов.')

h('Обсуждение и границы применимости')
p('Схема отделяет допуск по риску, ценность дополнительного наблюдения и ресурсное согласование. Простое увеличение порога уверенности не решает задачу распределения проверок между заявками. В то же время общая оптимизация не исправляет ошибочную содержательную связь: пререквизиты, рубрика и условия самостоятельности должны быть заданы до вычисления. Сильная зависимость между заданиями или использование результатов с помощью ИИ как самостоятельных испытаний нарушают основания (1).')
p('Существенный предел постановки – короткий горизонт и стационарное состояние во время диагностики. Для обучения, забывания и многократных проверок потребуется переходная модель. Разделяемые занятия, изменение модульного состава программы и связанный риск нескольких переходов также расширяют задачу за пределы (5). Представленный результат может использоваться как проверяемый подалгоритм более общей системы, но не заменяет метод согласованной оптимизации всей программы.')
p('Синтетическое обогащение информативными диагностиками облегчает наблюдение различий между алгоритмами и ограничивает внешнюю применимость количественных значений. Не проверены эмпирическая калибровка p и ρ, реальные стоимости отсрочки и ошибок, справедливость распределения ресурса между студентами. Аддитивная целевая функция может неодинаково обслуживать малочисленные группы; дополнительные ограничения обслуживания требуют явного включения в планирование. Оценка Sε относится только к округлению выигрышей при фиксированных альтернативных действиях и точных входных вероятностях.')
p('Анализ цифровизации образовательных услуг на региональных данных [24] относится к другому уровню наблюдения. Такие агрегаты полезны для контекста развития системы, однако не определяют индивидуальные вероятности успеха и стоимости ошибок в данном вычислительном опыте.')
p('В программном комплексе входом метода служат снимок состояния и версии правил, выходом – выбранные действия, потребление обоих ресурсов, исходный и округлённый выигрыши и цепочка предшественников. По этим данным можно повторить расчёт и объяснить, почему заявка получила диагностику либо отсрочку. Разработанный численный эксперимент выполнен отдельным модулем; функционирование этого оптимизатора на реальных учебных группах не заявляется.')

h('Заключение')
p('Получена схема численного решения конечной задачи согласованного выбора образовательных действий. Она объединяет точный рациональный расчёт апостериорного риска и диагностических потерь с динамическим программированием по общим ресурсам. Для заданной постановки доказаны допустимость восстановленного плана и аддитивная оценка отклонения целевой функции Sε. Эти свойства позволяют задавать требуемую точность до вычисления и проверять результат независимо от пользовательского интерфейса.')
p('Точный перебор подтвердил эталонный расчёт на 30 малых задачах; основная серия установила вычислительные характеристики для 20 наборов до 192 заявок. Полученные результаты обосновывают использование метода в указанном конечном классе задач. Следующие исследования должны проверить калибровку модели на самостоятельной диагностике и расширить согласование на динамику подготовки и структуру модулей. Педагогическая эффективность требует собственного эксперимента.')

