for block in blocks:
 if block['type']=='paragraph':
  block['text']=block['text'].replace('Вместе со значением хранится предшественник для восстановления плана.','Для восстановления плана можно хранить ссылки на предшественников. Исследовательская реализация хранит вместе со значением полную цепочку альтернатив и копирует её при продолжении состояния.')
  block['text']=block['text'].replace('При A=maxₛ|Aₛ| плотный вариант требует','При A=maxₛ|Aₛ| плотный вариант со скалярными значениями и ссылками на предшественников требует')
  if 'псевдополиномиален по ресурсным бюджетам' in block['text']:
   block['text']+=' В Python-прототипе копирование полной цепочки добавляет до O(S) операций на переход; приведённые времена включают эту стоимость.'
  block['text']=block['text'].replace('погрешности η достаточно выбрать ε≤η/S','погрешности ε₀ достаточно выбрать ε≤ε₀/S')
