# Additional sources and citations are renumbered by first appearance. Only
# square-bracket literature labels are rewritten; equation labels are untouched.
additions=json.loads((B/'bibliography_additions.json').read_text(encoding='utf8'))
refs.extend(v['reference'] for v in additions)
assert len(refs)==25
first=[]
pattern=re.compile(r'\[(\d+)\](?:[–-]\[(\d+)\])?')
for block in blocks:
 if block['type']=='paragraph':
  for match in pattern.finditer(block['text']):
   ids=range(int(match[1]),int(match[2])+1) if match[2] else [int(match[1])]
   for number in ids:
    if number not in first:first.append(number)
assert sorted(first)==list(range(1,26)),first
mapping={old:new for new,old in enumerate(first,1)}
def renumber(match):
 ids=list(range(int(match[1]),int(match[2])+1)) if match[2] else [int(match[1])]
 values=[mapping[number] for number in ids]
 if len(values)>1 and values==list(range(values[0],values[-1]+1)):
  return '['+str(values[0])+']–['+str(values[-1])+']'
 return ', '.join('['+str(v)+']' for v in values)
for block in blocks:
 if block['type']=='paragraph':block['text']=pattern.sub(renumber,block['text'])
refs=[refs[number-1] for number in first]
(B/'citation_mapping.json').write_text(json.dumps({'old_to_new':mapping,'first_appearance_old_ids':first,'digitarin_new_ids':[mapping[24],mapping[25]]},ensure_ascii=False,indent=2),encoding='utf8')

citations=' '.join(x.get('text','') for x in blocks)
for a,z in re.findall(r'\[(\d+)\]–\[(\d+)\]',citations):citations+=''.join('['+str(i)+']' for i in range(int(a),int(z)+1))
assert all('['+str(i)+']' in citations for i in range(1,26))
